"""Explicit local development-only business fixtures; never claim these were generated by AI."""

from uuid import UUID, uuid4

from sqlalchemy.engine import make_url

from app.bootstrap.config import get_settings
from app.modules.maintenance_order.domain.models import WorkOrder
from app.modules.operation_event.domain.models import ProductionEvent, ProductionEventVersion
from app.shared.db import Database
from app.shared.platform.models import WorkflowRun
from app.shared.platform.service import add_audit
from app.shared.security.authentication.schemas import AuthenticatedIdentity
from app.shared.security.authorization.permissions import Permissions as P
from app.shared.security.authorization.repository import load_current_user
from app.shared.security.identity.models import UserAccount


async def create_synthetic_order(user_id):
    settings = get_settings()
    if settings.app_env not in {"development", "test"} or make_url(
        settings.database_url
    ).host not in {"localhost", "127.0.0.1"}:
        raise ValueError("synthetic fixture seeding is restricted to a local development database")
    database = Database(settings.database_url)
    try:
        async with database.session_factory() as session:
            account = await session.get(UserAccount, UUID(str(user_id)))
            if not account or not account.active:
                raise ValueError("development operator is unavailable")
            user = await load_current_user(
                session,
                AuthenticatedIdentity(
                    user_id=account.id,
                    issuer=account.external_issuer,
                    subject=account.external_subject,
                    username=account.username,
                    display_name=account.display_name,
                    organization_unit_id=account.organization_unit_id,
                    authz_version=account.authz_version,
                ),
            )
            if not user.has_global_permission(P.ALL):
                raise ValueError("synthetic fixture creation requires the local administrator")
            marker = "[合成验收] fixture-" + uuid4().hex[:10]
            event = ProductionEvent(
                organization_unit_id=account.organization_unit_id,
                title=marker,
                event_type="软件验收",
                severity="low",
                business_status="candidate",
                created_by=account.id,
            )
            session.add(event)
            await session.flush()
            version = ProductionEventVersion(
                event_id=event.id,
                version=1,
                source="manual",
                description=marker + "；人工软件夹具，不使用模型，不授权现场动作。",
                structured_data={
                    "provenance": "synthetic_fixture_no_model",
                    "expert_validated": False,
                },
                created_by=account.id,
            )
            session.add(version)
            await session.flush()
            event.current_version_id = version.id
            workflow = WorkflowRun(
                workflow_type="synthetic_acceptance_fixture",
                resource_type="production_event",
                resource_id=event.id,
                organization_unit_id=account.organization_unit_id,
                status="completed",
                current_node="fixture_created",
                thread_id="fixture-" + uuid4().hex,
                state_snapshot={
                    "provenance": "synthetic_fixture_no_model",
                    "expert_validated": False,
                },
            )
            session.add(workflow)
            await session.flush()
            order = WorkOrder(
                organization_unit_id=account.organization_unit_id,
                event_id=event.id,
                source_workflow_run_id=workflow.id,
                order_no="SYN-" + uuid4().hex,
                title=marker,
                description=version.description,
                risk_level="low",
                status="draft",
                version=1,
                created_by=account.id,
            )
            session.add(order)
            await session.flush()
            await add_audit(
                session,
                user=user,
                action="acceptance.synthetic_fixture.create",
                resource_type="work_order",
                resource_id=order.id,
                reason=version.description,
                after={"provenance": "synthetic_fixture_no_model", "event_id": str(event.id)},
            )
            await session.commit()
            return {
                "work_order_id": str(order.id),
                "event_id": str(event.id),
                "event_version_id": str(version.id),
                "fixture_provenance": "synthetic_fixture_no_model",
            }
    finally:
        await database.dispose()
